function heading(text, level = HeadingLevel.HEADING_1) {
  return new Paragraph({ heading: level, children: [new TextRun(text)] });
}

function para(text, opts = {}) {
  const runs = Array.isArray(text)
    ? text
    : [new TextRun({ text, ...opts })];
  return new Paragraph({ spacing: { after: 160 }, children: runs });
}

function boldPara(label, text) {
  return new Paragraph({
    spacing: { after: 160 },
    children: [
      new TextRun({ text: label, bold: true }),
      new TextRun({ text }),
    ],
  });
}

function bulletItem(text, ref = "bullets", level = 0) {
  const runs = Array.isArray(text) ? text : [new TextRun(text)];
  return new Paragraph({
    numbering: { reference: ref, level },
    spacing: { after: 80 },
    children: runs,
  });
}

function numberedItem(text, ref = "numbers", level = 0) {
  const runs = Array.isArray(text) ? text : [new TextRun(text)];
  return new Paragraph({
    numbering: { reference: ref, level },
    spacing: { after: 80 },
    children: runs,
  });
}

function makeCell(text, opts = {}) {
  const { bold, shading, width, alignment } = opts;
  const runs = Array.isArray(text) ? text : [new TextRun({ text, bold: !!bold, font: "Arial", size: 20 })];
  return new TableCell({
    borders,
    width: width ? { size: width, type: WidthType.DXA } : undefined,
    shading: shading ? { fill: shading, type: ShadingType.CLEAR } : undefined,
    margins: { top: 60, bottom: 60, left: 100, right: 100 },
    children: [new Paragraph({ alignment: alignment || AlignmentType.LEFT, children: runs })],
  });
}

function makeTable(headers, rows, colWidths) {
  const totalWidth = colWidths.reduce((a, b) => a + b, 0);
  return new Table({
    width: { size: totalWidth, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [
      new TableRow({
        children: headers.map((h, i) =>
          makeCell(h, { bold: true, shading: SECONDARY, width: colWidths[i] })
        ),
      }),
      ...rows.map(
        (row) =>
          new TableRow({
            children: row.map((cell, i) => makeCell(cell, { width: colWidths[i] })),
          })
      ),
    ],
  });
}

// Override header text color for table headers to white
function makeHeaderCell(text, width) {
  return new TableCell({
    borders,
    width: { size: width, type: WidthType.DXA },
    shading: { fill: SECONDARY, type: ShadingType.CLEAR },
    margins: { top: 60, bottom: 60, left: 100, right: 100 },
    children: [new Paragraph({ children: [new TextRun({ text, bold: true, font: "Arial", size: 20, color: WHITE })] })],
  });
}

function makeTableWithWhiteHeaders(headers, rows, colWidths) {
  const totalWidth = colWidths.reduce((a, b) => a + b, 0);
  return new Table({
    width: { size: totalWidth, type: WidthType.DXA },
    columnWidths: colWidths,
    rows: [
      new TableRow({
        children: headers.map((h, i) => makeHeaderCell(h, colWidths[i])),
      }),
      ...rows.map(
        (row) =>
          new TableRow({
            children: row.map((cell, i) => makeCell(cell, { width: colWidths[i] })),
          })
      ),
    ],
  });
}

function spacer() {
  return new Paragraph({ spacing: { after: 80 }, children: [] });
}

